def choose_move(observation):
    def sgn(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def pos(x, default=0):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            return x[0], x[1]
        return default, default

    def nearest(targets, sx, sy):
        best = None
        best_d = None
        for item in targets or []:
            if not isinstance(item, (list, tuple)) or len(item) < 2:
                continue
            x, y = item[0], item[1]
            d = abs(x - sx) + abs(y - sy)
            if best is None or d < best_d:
                best = (x, y)
                best_d = d
        return best

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position"), 0)
    ox, oy = pos(observation.get("opponent_position"), sx)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return [sgn(ox - sx), sgn(oy - sy)]
        gw = observation.get("grid_width", 0)
        gh = observation.get("grid_height", 0)
        corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
        target = None
        best_d = None
        for tx, ty in corners:
            d = abs(tx - ox) + abs(ty - oy)
            if target is None or d > best_d:
                target = (tx, ty)
                best_d = d
        if target is None:
            return [0, 0]
        return [sgn(target[0] - sx), sgn(target[1] - sy)]

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        best = nearest(targets, sx, sy)
        if best is not None:
            return [sgn(best[0] - sx), sgn(best[1] - sy)]
        ow = observation.get("opponent_base")
        if isinstance(ow, (list, tuple)) and len(ow) >= 2:
            return [sgn(ow[0] - sx), sgn(ow[1] - sy)]
        return [sgn(ox - sx), sgn(oy - sy)]

    resources = observation.get("resources") or observation.get("resource_positions") or []
    best = nearest(resources, sx, sy)
    if best is not None:
        return [sgn(best[0] - sx), sgn(best[1] - sy)]

    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)
    center = (gw // 2, gh // 2) if gw and gh else (sx, sy)
    if abs(ox - sx) + abs(oy - sy) <= 2:
        return [sgn(sx - ox), sgn(sy - oy)]
    return [sgn(center[0] - sx), sgn(center[1] - sy)]

